import{_ as t,o as d,c as s,a3 as o}from"./chunks/framework.B02wg2PO.js";const k=JSON.parse('{"title":"The Web App","description":"","frontmatter":{},"headers":[],"relativePath":"reference/web-app.md","filePath":"reference/web-app.md"}'),a={name:"reference/web-app.md"};function i(n,e,r,c,h,l){return d(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-web-app" tabindex="-1">The Web App <a class="header-anchor" href="#the-web-app" aria-label="Permalink to &quot;The Web App&quot;">​</a></h1><p><code>client/</code> is the dashboard: a React single-page app built with Vite, served by the orchestrator itself in production. It has no router and no component library. State lives in Zustand stores, data arrives over <code>/api/*</code> and one WebSocket, and every screen is a plain module under <code>client/src/views/</code>.</p><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Version</th><th>Role</th></tr></thead><tbody><tr><td><code>react</code> / <code>react-dom</code></td><td>^18.3.1</td><td>The UI</td></tr><tr><td><code>zustand</code></td><td>^5.0.2</td><td>All client state (<code>store</code>, <code>session</code>, <code>members</code>, <code>voice</code>)</td></tr><tr><td><code>vite</code></td><td>^6.0.7</td><td>Dev server and production bundler</td></tr><tr><td><code>typescript</code></td><td>^5.7.2</td><td><code>tsc --noEmit</code> gates every build</td></tr><tr><td><code>@vitejs/plugin-react</code></td><td>^4.3.4</td><td>Fast Refresh</td></tr><tr><td><code>react-grab</code></td><td>^0.1.47</td><td>Dev dependency only</td></tr></tbody></table><p>There is no CSS framework. Styling is inline styles plus two stylesheets, <code>src/styles/global.css</code> and <code>src/styles/landing.css</code>, with a palette resolved through <code>src/theme.ts</code>. Fonts (Bricolage Grotesque, Outfit, Spline Sans, Spline Sans Mono) are loaded from Google Fonts in <code>client/index.html</code>.</p><h2 id="url-routes" tabindex="-1">URL routes <a class="header-anchor" href="#url-routes" aria-label="Permalink to &quot;URL routes&quot;">​</a></h2><p>The app reads <code>window.location.pathname</code> exactly twice. <code>App.tsx</code> decides between the public landing page and the dashboard runtime; <code>AuthGate</code> parses one-shot token links in cloud mode and consumes them with <code>history.replaceState</code>.</p><table tabindex="0"><thead><tr><th>Path</th><th>Renders</th></tr></thead><tbody><tr><td><code>/</code></td><td><code>views/Landing.tsx</code> — the public marketing page</td></tr><tr><td><code>/app</code></td><td>The dashboard runtime (<code>RuntimeApp</code>, lazy-loaded). The landing page&#39;s CTA links here and preloads the chunk on hover/focus</td></tr><tr><td>any other non-<code>/api</code> path</td><td>Also the dashboard runtime — the pathname check is only <code>!== &#39;/&#39;</code></td></tr><tr><td><code>/verify?token=…</code></td><td>Cloud: the email-verification screen inside <code>AuthGate</code></td></tr><tr><td><code>/reset?token=…</code></td><td>Cloud: password reset</td></tr><tr><td><code>/invite?token=…</code></td><td>Cloud: accept an invitation (<code>auth/InviteFlow.tsx</code>)</td></tr><tr><td><code>/login?error=…</code></td><td>Cloud: the login screen with an OAuth error notice</td></tr></tbody></table><p>The runtime is split out of <code>App.tsx</code> on purpose, so a visitor on the landing page never downloads the dashboard bundle.</p><h2 id="boot-sequence" tabindex="-1">Boot sequence <a class="header-anchor" href="#boot-sequence" aria-label="Permalink to &quot;Boot sequence&quot;">​</a></h2><p><code>RuntimeApp</code> fetches <code>/api/bootstrap</code> first, retrying with exponential backoff capped at 15 s until it succeeds. The response&#39;s <code>mode</code> decides everything after that.</p><p><strong>Local mode.</strong> <code>GET /api/onboarding</code> runs the doctor. If the report is <code>ready</code> and an owner name is set, the runtime starts; otherwise the <code>Onboarding</code> view renders the failing checks and a setup action. A passing doctor is cached in <code>localStorage</code> under <code>saidi_doctor_ok</code>, keyed by the build&#39;s <code>__APP_VERSION__</code>, so later loads of the same build skip the gate entirely and go straight to the dashboard.</p><p><strong>Cloud mode.</strong> <code>installCloudFetch</code> is wired up and <code>AuthGate</code> takes over with a small screen machine — login, signup, forgot, reset, verify, invite, create-org. When a user and an active org are in hand it calls <code>enter(orgId)</code> and the dashboard boots.</p><p>Both paths then do the same three things: <code>loadInitialState()</code>, <code>ensureConnected()</code>, and render <code>AppShellSkeleton</code> until the first snapshot lands. The initial load posts <code>/api/state/reload</code> (re-hydrating the server&#39;s in-memory stores from MongoDB, so external database edits show without a restart) and falls back to a plain <code>GET /api/state</code>, retrying at 1 s, 2 s, 4 s… capped at 15 s. That shared promise is the first-paint barrier, so the dashboard never mounts against defaults or another org&#39;s stale state.</p><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><p>Inside the dashboard there is no URL routing. The active screen is a <code>tab</code> field in the Zustand store; <code>components/Shell.tsx</code> switches on it. An inaccessible tab falls back to Home.</p><table tabindex="0"><thead><tr><th><code>tab</code></th><th>View</th><th>What it does</th></tr></thead><tbody><tr><td><code>overview</code></td><td><code>views/Overview.tsx</code></td><td>Home — the constellation: the orchestrator at the centre, departments orbiting, agents inside a department. Pan, wheel-zoom, draggable nodes; layouts persisted in <code>localStorage</code></td></tr><tr><td><code>logs</code></td><td><code>views/Chat.tsx</code></td><td>Chat — a rail of main chats plus every run as a working chat, and the active conversation as bubbles</td></tr><tr><td><code>runs</code></td><td><code>views/Runs.tsx</code></td><td>Runs — the attention lane (decisions answerable in place), live runs as dense rows, the finished tail folded by day, and a peek rail for the selected run</td></tr><tr><td><code>crons</code></td><td><code>views/Crons.tsx</code></td><td>Schedules — clock-triggered work as cards, with an inline create/edit form</td></tr><tr><td><code>reflexes</code></td><td><code>views/Reflexes.tsx</code></td><td>Reflexes — event-triggered rules as cards, plus the live activity console</td></tr><tr><td><code>memory</code></td><td><code>views/Memory.tsx</code></td><td>Memory — the CORE / PROJECTS / AGENTS lattice with search</td></tr><tr><td><code>market</code></td><td><code>views/Marketplace.tsx</code></td><td>Marketplace — browse, preview, install, rate, publish, and manage packages</td></tr><tr><td><code>org</code></td><td><code>views/Org.tsx</code></td><td>Team (cloud) — members, invites, budgets, permissions, agent access</td></tr><tr><td><code>admin</code></td><td><code>views/PlatformAdmin.tsx</code></td><td>Platform (cloud superadmin) — every workspace, credit grants, suspend/reinstate, inspect</td></tr><tr><td><code>settings</code></td><td><code>views/Settings.tsx</code></td><td>Settings — renders one section, full width</td></tr></tbody></table><p>Two tabs expand sub-navigation in the sidebar rather than in-page tab strips:</p><table tabindex="0"><thead><tr><th>Parent</th><th>Sections</th></tr></thead><tbody><tr><td>Settings</td><td><code>general</code>, <code>providers</code>, <code>runs</code>, <code>costs</code>, <code>approvals</code>, <code>connections</code>, <code>system</code></td></tr><tr><td>Team</td><td><code>members</code>, <code>billing</code>, <code>usage</code></td></tr></tbody></table><p><code>views/Settings.tsx</code> is only a selector; <code>views/SystemSettings.tsx</code> is the shell that owns loading, drafts, and autosave for all seven sections, and delegates rendering to <code>views/settings/GeneralTab.tsx</code>, <code>ProvidersTab.tsx</code>, <code>RunsTab.tsx</code>, <code>CostsTab.tsx</code>, and <code>SystemTabs.tsx</code> (which embeds <code>TelegramSettings</code>, <code>ImportSettings</code>, and <code>Onboarding</code>).</p><p>Views reached from inside another screen rather than from the sidebar:</p><table tabindex="0"><thead><tr><th>View</th><th>Opened from</th></tr></thead><tbody><tr><td><code>views/EntityPage.tsx</code></td><td>Memory or the Home constellation — one agent/project with Memory / Files / Skills / MCP / Profile tabs</td></tr><tr><td><code>views/ReflexWizard.tsx</code></td><td>Reflexes — the four-step create/edit modal (Event → Filter → Action → Review)</td></tr><tr><td><code>views/ReflexActivity.tsx</code></td><td>Reflexes — pending approvals, live event feed, fire history</td></tr><tr><td><code>views/OrgInvites.tsx</code></td><td>Team → Members</td></tr><tr><td><code>views/TeamFinance.tsx</code></td><td>Team → Billing / Usage</td></tr></tbody></table><h2 id="chrome-and-overlays" tabindex="-1">Chrome and overlays <a class="header-anchor" href="#chrome-and-overlays" aria-label="Permalink to &quot;Chrome and overlays&quot;">​</a></h2><p><code>Shell.tsx</code> is a two-column grid — a 66 px top bar row, then the sidebar and the main column. Below the mobile breakpoint the sidebar becomes an off-canvas drawer and the content takes the full width.</p><table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td><code>components/TopBar.tsx</code></td><td>Workspace name, credits, effort, theme switch, user menu</td></tr><tr><td><code>components/SideBar.tsx</code></td><td>Everyday rows (Home / Chat / Runs) and a Manage group; collapses to icons, badges runs parked at an approval gate</td></tr><tr><td><code>components/CommandBar.tsx</code></td><td>The global composer: text/voice switch, auto-growing input, slash palette, queue indicator, STOP, EXECUTE</td></tr><tr><td><code>components/Feed.tsx</code></td><td>Chat rows, streaming segments, message state, tool-call detail toggles, confirm cards</td></tr><tr><td><code>components/RunChat.tsx</code></td><td>Full-window chat for one run — status header, agent flow strip, thread, verbose tool timeline, approval gate, composer</td></tr><tr><td><code>components/ChatFull.tsx</code></td><td>Full-window chat mode for the main conversation</td></tr><tr><td><code>components/ConfirmLayer.tsx</code></td><td>Pending approvals floated above every view, mounted once</td></tr><tr><td><code>components/MemoryDrawer.tsx</code></td><td>Slide-in editor for a single memory file</td></tr><tr><td><code>components/NewRunDialog.tsx</code></td><td>The one dialog for starting a run, including saved playbooks</td></tr><tr><td><code>components/WhatsNewDialog.tsx</code> / <code>UpdateAvailableDialog.tsx</code></td><td>Release notes and the update prompt</td></tr></tbody></table><p>Typing <code>/</code> in the composer opens the slash palette. Selecting an entry runs a real app action — the raw string is never sent to the model.</p><table tabindex="0"><thead><tr><th>Command</th><th>Action</th></tr></thead><tbody><tr><td><code>/clear</code>, <code>/new</code></td><td>Clear the conversation and reset the server session</td></tr><tr><td><code>/context</code></td><td>Show model, context occupancy, throughput, and cache usage from the last turn</td></tr><tr><td><code>/overview</code>, <code>/runs</code>, <code>/memory</code>, <code>/logs</code>, <code>/market</code></td><td>Switch tab</td></tr><tr><td><code>/theme</code></td><td>Cycle the colour theme</td></tr><tr><td><code>/voice</code>, <code>/text</code></td><td>Switch input mode</td></tr><tr><td><code>/help</code></td><td>List the commands</td></tr></tbody></table><h2 id="talking-to-the-orchestrator-—-rest" tabindex="-1">Talking to the orchestrator — REST <a class="header-anchor" href="#talking-to-the-orchestrator-—-rest" aria-label="Permalink to &quot;Talking to the orchestrator — REST&quot;">​</a></h2><p><code>src/lib/api.ts</code> holds the typed REST calls; <code>src/lib/cloud.ts</code> holds the auth, org, and platform-admin calls. The rule the module states for itself: all dashboard data flows through <code>getState()</code> — nothing is hardcoded in the views.</p><table tabindex="0"><thead><tr><th>Group</th><th>Endpoints</th></tr></thead><tbody><tr><td>Snapshot</td><td><code>/api/state</code>, <code>/api/state/reload</code></td></tr><tr><td>Chats &amp; runs</td><td><code>/api/chats</code>, <code>/api/runs</code>, <code>/api/runs/search</code>, <code>/api/run-asset</code>, <code>/api/chat-asset</code>, <code>/api/chat/upload</code>, <code>/api/playbooks</code></td></tr><tr><td>Entities</td><td><code>/api/entity</code>, <code>/api/entity/mcp</code>, <code>/api/entity/mcp/auth</code>, <code>/api/browse</code>, <code>/api/memory</code></td></tr><tr><td>Automation</td><td><code>/api/crons</code>, <code>/api/reflexes</code>, <code>/api/reflexes/log</code>, <code>/api/reflexes/pending</code></td></tr><tr><td>Settings</td><td><code>/api/settings</code>, <code>/api/settings/system</code>, <code>/api/settings/agents/…</code>, <code>/api/settings/projects/…</code>, <code>/api/secrets</code>, <code>/api/providers</code>, <code>/api/telegram</code></td></tr><tr><td>Marketplace</td><td><code>/api/marketplace/*</code></td></tr><tr><td>Setup</td><td><code>/api/onboarding</code>, <code>/api/onboarding/setup</code>, <code>/api/import/agents</code>, <code>/api/import/memory</code></td></tr><tr><td>Cloud</td><td><code>/api/bootstrap</code>, <code>/api/auth/*</code>, <code>/api/orgs</code>, <code>/api/members</code>, <code>/api/credits</code>, <code>/api/admin/*</code></td></tr></tbody></table><p>Full request and response shapes are in the <a href="/docs/reference/http-api">HTTP API</a> reference; the TypeScript types the client uses are in <code>src/lib/protocol.ts</code>.</p><h2 id="talking-to-the-orchestrator-—-websocket" tabindex="-1">Talking to the orchestrator — WebSocket <a class="header-anchor" href="#talking-to-the-orchestrator-—-websocket" aria-label="Permalink to &quot;Talking to the orchestrator — WebSocket&quot;">​</a></h2><p><code>src/ws/socket.ts</code> owns exactly one socket for the app&#39;s lifetime. The URL is built from the page origin, so the socket always shares an origin with the API:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> proto</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> location.protocol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https:&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;wss&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ws&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> orgQS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orgId </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`?org=\${</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">encodeURIComponent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">orgId</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}\`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> WebSocket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}://\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">location</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/ws\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">orgQS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The server listens on path <code>/ws</code>. In cloud mode the session cookie rides the upgrade and <code>?org=</code> selects the room.</p><p><strong>Client → server.</strong></p><table tabindex="0"><thead><tr><th>Message</th><th>Purpose</th></tr></thead><tbody><tr><td><code>user</code></td><td>A directive, with <code>id</code>, <code>mode</code> (<code>text</code>/<code>voice</code>), optional <code>conversationId</code> and attachments</td></tr><tr><td><code>confirm_response</code></td><td>Approve or deny a pending confirm</td></tr><tr><td><code>cancel</code></td><td>Cancel one message by id</td></tr><tr><td><code>reset</code></td><td>Drop the session and flush the queue</td></tr><tr><td><code>realtime_tool_call</code> / <code>realtime_cancel</code> / <code>realtime_transcript</code></td><td>Voice-mode turn plumbing</td></tr><tr><td><code>ping</code></td><td>App-level heartbeat; the server replies <code>pong</code></td></tr></tbody></table><p><strong>Server → client.</strong> The union covers turn lifecycle (<code>turn_start</code>, <code>working</code>, <code>status</code>, <code>delta</code>, <code>thinking</code>, <code>stream_snapshot</code>, <code>turn_end</code>, <code>turn_cancelled</code>, <code>error</code>), chat (<code>chat_event</code>, <code>confirm</code>, <code>message_state</code>, <code>queue</code>, <code>cleared</code>, <code>vitals</code>), runs (<code>run_update</code>, <code>run_removed</code>, <code>run_event</code>, <code>run_delta</code>, <code>run_segment_end</code>, <code>run_truncated</code>), automation (<code>cron_update</code>, <code>cron_removed</code>, <code>reflex_update</code>, <code>reflex_removed</code>, <code>reflex_fired</code>, <code>reflex_event</code>, <code>reflex_fire</code>, <code>reflex_pending</code>, <code>reflex_resolved</code>), liveness (<code>agent_state</code>, <code>channel_log</code>), and invalidations (<code>state_dirty</code>, <code>governance_dirty</code>, <code>wallet</code>, <code>pong</code>). See <a href="/docs/reference/events-and-websocket">Events &amp; WebSocket</a>.</p><p>Three frames are handled by the transport rather than the store reducer: <code>pong</code> is dropped, <code>realtime_tool_result</code> resolves a pending tool promise, and <code>state_dirty</code> triggers a <code>/api/state</code> refetch.</p><p><strong>Liveness.</strong> A browser can leave a socket half-open — <code>readyState</code> stays <code>OPEN</code> and <code>onclose</code> never fires — after sleep or network loss. The transport therefore pings every 25 s, checks every 10 s, and force-closes a socket that has received no inbound frame for 40 s, which routes into the normal <code>onclose</code> → reconnect path. Reconnects are scheduled once, 1.5 s later, guarded so a wake-driven reconnect and a pending timer cannot open two sockets. <code>visibilitychange</code> and <code>online</code> listeners reconnect and re-pull state immediately. Close code <code>4401</code> means the cloud session is gone: reconnecting stops and the page reloads back through the auth gate.</p><p><strong>Snapshot races.</strong> Each <code>/api/state</code> request takes a sequence number and only the newest response applies. Liveness frames that arrive while a snapshot is in flight are captured and re-applied after hydration, so a just-lit or just-idled agent is never reverted to the snapshot&#39;s older status.</p><p>Under Vite HMR the module disposes its socket and timers explicitly — a ghost socket from a previous module instance would apply every server frame into the store a second time.</p><h2 id="dev-server" tabindex="-1">Dev server <a class="header-anchor" href="#dev-server" aria-label="Permalink to &quot;Dev server&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # repo root: server + client together</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:client</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # just Vite</span></span></code></pre></div><p>Vite listens on port <strong>5317</strong> and proxies to the backend so the SPA and the orchestrator share an origin:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5317</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  proxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;/api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { target: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BACKEND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, changeOrigin: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;/ws&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { target: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BACKEND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ws: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, changeOrigin: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>BACKEND</code> is <code>SAIDI_BACKEND</code> or <code>http://127.0.0.1:4317</code>. The app version is read from the root <code>package.json</code> at config time and injected as <code>__APP_VERSION__</code>, so the client can decide synchronously — with no network call — whether the doctor already passed for this build.</p><p>There is exactly one app URL in development. When <code>SAIDI_DEV</code> is set, the Express server does <strong>not</strong> serve a second, build-frozen copy of the SPA; any non-<code>/api</code> GET is redirected (302) to <code>SAIDI_CLIENT_URL</code> or <code>http://&lt;hostname&gt;:5317</code>. A stale second copy is what made live updates look broken.</p><h2 id="production-build-and-serving" tabindex="-1">Production build and serving <a class="header-anchor" href="#production-build-and-serving" aria-label="Permalink to &quot;Production build and serving&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # build:client then build:server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # tsc --noEmit &amp;&amp; vite build → client/dist</span></span></code></pre></div><p>The build fails on a type error before Vite runs. Output goes to <code>client/dist</code> with <code>emptyOutDir</code> on.</p><p>Without <code>SAIDI_DEV</code>, the orchestrator is the single origin. It serves <code>&lt;repo&gt;/client/dist</code> statically and falls back to <code>index.html</code> for any non-<code>/api</code> GET so deep links and client-side routing boot. If the build is missing, the server answers <code>503</code> with the plain-text message <code>Client not built. Run npm run build.</code> rather than a blank page.</p><table tabindex="0"><thead><tr><th>Script</th><th>Effect</th></tr></thead><tbody><tr><td><code>npm run build:client</code></td><td>Typecheck + Vite build into <code>client/dist</code></td></tr><tr><td><code>npm run build:server</code></td><td>Bundle the orchestrator into <code>dist/</code></td></tr><tr><td><code>npm start</code></td><td>Run the server from TypeScript source (<code>tsx</code>)</td></tr><tr><td><code>npm run start:prod</code></td><td>Run the bundled <code>dist/server.js</code></td></tr><tr><td><code>npm run typecheck</code></td><td><code>tsc --noEmit</code> for both the server and the client</td></tr></tbody></table><p><code>client/package.json</code> carries its own version, kept in lock-step with the root by release-please. Deployment topology is covered in <a href="/docs/operations/deployment">Deployment</a>; what a run looks like behind the Runs screen is in <a href="/docs/concepts/runs">Runs</a>.</p>`,54)])])}const g=t(a,[["render",i]]);export{k as __pageData,g as default};
